const x=$input.first().json,a=x.qualification;let error=x.llmParseError||'';
if(!error){
 if(!a)error='missing AI output';
 else if(!['high','medium','low'].includes(a.fit))error='invalid fit';
 else if(typeof a.score!=='number'||!Number.isFinite(a.score)||a.score<0||a.score>10)error='invalid score';
 else if(typeof a.confidence!=='number'||!Number.isFinite(a.confidence)||a.confidence<0||a.confidence>1)error='invalid confidence';
 else if(typeof a.reason!=='string'||!a.reason.trim())error='empty reason';
 else if(!Array.isArray(a.missing_info)||a.missing_info.some(m=>typeof m!=='string'))error='invalid missing_info';
}
x.aiValid=!error;x.aiValidationError=error;
if(x.aiValid){const pr=a.score>=8.5?'hot':a.score>=6.5?'warm':a.score>=4.5?'lukewarm':'cold';x.qualification={...a,priority:pr,next_action:pr==='hot'?'Prepare prompt human outreach':'Prepare tailored follow-up'};}
x.reviewReasonCandidate=error?'ai_validation':a.confidence<0.7?'low_confidence':a.missing_info.length>0?'missing_info':'';
x.reviewNeeded=!!x.reviewReasonCandidate;return [{json:x}];

